import {scienceLessons,scienceSteps,normalizeScience,scienceQuestionId} from './science-data.js';
import {scienceScene,scienceChoice,scienceMotionScenes,animateScienceScene} from './science-scenes.js';
import {narrationLine,narrationControls} from './narration.js';
// Bangla translations that the lessons already contain, by English sentence.
const lessonBangla=new Map(scienceLessons.flatMap(l=>[...l.sentences,...l.questions,l.recap,...l.sentences.flatMap(s=>s.action?.options||[])]).map(s=>[s.text||s.prompt,s.meaning]));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,attrs='',kind='')=>'<button class="btn '+kind+'" data-action="stages-science-'+action+'" '+attrs+'>'+label+'</button>';
const meaning=s=>'<details class="math-meaning science-meaning"><summary lang="bn">মানে · Bangla help</summary><p lang="bn">'+esc(s)+'</p></details>';
export function createScienceFlow({getProgress,save,render,play,stop,onAttempt,isSaved}){
 let selected=null,stopMotion=()=>{},lastBound=null,motionSerial=0;
 const state=()=>getProgress().science,lesson=()=>scienceLessons.find(l=>l.id===selected),p=()=>state().lessons[selected],current=()=>scienceSteps(lesson())[p().step];
 const ensure=()=>{getProgress().science??=normalizeScience(null);};
 const attempt=q=>p().attempts[q.id]??={tries:0,misses:0,assisted:false,firstCorrect:null};
 const correct=q=>p().answers[q.id]===q.answer;
 function displayed(){const st=current(),option=st.action?.options.find(o=>o.id===p().experiments[st.action.id]?.value);return option?{...st,...option}:st;}
 function ready(){const st=current();return st.type==='question'?correct(st):st.action?st.action.options.every(o=>p().experiments[st.action.id]?.tried.includes(o.id)):true;}
 function open(id){if(!scienceLessons.some(l=>l.id===id))return;ensure();selected=id;state().current=id;const fresh=!state().lessons[id];state().lessons[id]??=normalizeScience({lessons:{[id]:{}}}).lessons[id];if(fresh)while(current().type==='word'&&(state().wordsMet.includes(current().word)||getProgress().playful?.wordsMet.includes(current().word.toLowerCase())))p().step++;save();render();}
 function home(){ensure();const l=scienceLessons.find(l=>l.id===state().current);return '<section class="science-library math-library"><div class="eyebrow">English for Science · All ages welcome</div><h1>Look, listen and explore</h1><p>Little discoveries. One small idea at a time.</p>'+(l?'<div class="resume-strip"><span>'+esc(l.title)+'</span>'+button('Continue your saved lesson →','open','data-id="'+l.id+'"','primary')+'</div>':'')+'<div class="science-lesson-cards math-lesson-cards">'+scienceLessons.map((l,n)=>{const cur=l.id===state().current,next=!cur&&scienceLessons[n-1]?.id===state().current;return '<button class="science-lesson-card math-lesson-card'+(cur?' is-current':'')+(state().lessons[l.id]?.done?' is-done':'')+'" data-action="stages-science-open" data-id="'+l.id+'" aria-current="'+(cur?'true':'false')+'"><em class="lesson-number" aria-label="Lesson '+(n+1)+'">'+(n+1)+'</em>'+scienceScene(l.scene,true)+'<b>'+esc(l.title)+'</b><span>'+(state().lessons[l.id]?.done?'Practised ★':cur?'Continue here':next?'Up next':state().lessons[l.id]?'Continue saved place':'Start exploring')+'</span></button>';}).join('')+'</div><p class="math-guidance">Choose any lesson. Pictures, listening and help are welcome.</p></section>';}
 function html(){const l=lesson(),pr=p(),st=displayed(),i=pr.step,total=scienceSteps(l).length;let body='',navigation='';
  if(st.type==='finish')body='<div class="math-star" aria-label="One completion star">★</div><h2>You explored '+esc(l.title)+'</h2><p>Your practice is saved. Come back and explore again.</p>'+(nextLesson()?button('Next lesson · '+esc(nextLesson().title)+' →','next-lesson','','primary'):'')+button('Back to lessons','back','',nextLesson()?'':'primary')+button('Explore this lesson again','revisit')+'<p class="math-guidance">A star records practice, not verified independent reading or science mastery.</p>';
  else{body=(st.type==='word'?narrationLine(st.word,{key:'science-word:'+st.word,bn:st.meaning,cls:'science-vocab-word math-vocab-word'}):'')+scienceScene(st.scene)+narrationLine(st.type==='question'?st.prompt:st.text,{bn:st.type==='word'?lessonBangla.get(st.text):st.meaning,cls:'sentence math-sentence science-sentence'});
   if(st.action){const tested=pr.experiments[st.action.id]?.tried||[];body+='<div class="science-experiment-controls" role="group" aria-label="'+esc(st.action.kind==='switch'?'Pretend light switch':'Try the demonstration')+'">'+st.action.options.map(o=>button(esc(o.label)+(tested.includes(o.id)?' ✓':''),'explore','data-value="'+o.id+'" aria-pressed="'+(pr.experiments[st.action.id]?.value===o.id)+'"')).join('')+'</div><p class="science-experiment-help" role="status">'+(ready()?'✓ You explored each action. Choose any to replay.':'Try each action, then choose Next.')+'</p>';}
   if(st.type==='question'){const a=attempt(st),solved=correct(st),answer=pr.answers[st.id],choices=a.misses>=2&&!solved?st.choices.filter(c=>c.id===st.answer||c.id===st.choices.find(c=>c.id!==st.answer).id):st.choices;body+='<div class="math-answer-choices science-choices" role="group" aria-label="Choose one picture">'+choices.map(c=>'<button class="math-choice science-choice '+(answer&&c.id===st.answer?'correct':answer===c.id?'retry':'')+'" data-action="stages-science-answer" data-value="'+c.id+'" aria-label="'+esc(c.label)+'" '+(solved?'disabled':'')+'>'+scienceChoice(c)+'</button>').join('')+'</div><p class="math-feedback science-feedback '+(solved?'correct':'')+'" role="status">'+(solved?'✓ '+esc(st.feedback):a.misses?esc(st.hint):'Look, then choose a picture.')+'</p>'+(a.misses&&!solved?'<p class="math-demonstration science-demonstration">The answer is <b>'+esc(st.choices.find(c=>c.id===st.answer).label)+'</b>. '+esc(st.feedback.replace(/^Yes!\s*/,''))+(a.misses>=2?' Try again with two choices.':'')+'</p>':'');}
   body+=narrationControls()+'<div class="math-audio-controls science-audio-controls">'+button('Stop','stop')+(scienceMotionScenes.has(st.scene)?button('Replay the action','animation'):'')+'</div>';
   navigation='<div class="math-navigation">'+button('← Previous','previous',i===0?'disabled':'')+'<span>'+(i+1)+' of '+(total-1)+'</span>'+button(st.type==='recap'?'Finish ★':'Next →','next',ready()?'':'disabled','primary')+'</div>';
  }
  return '<div class="lesson-head">'+button('← English for Science','back')+'<span class="lesson-meta" id="save-status">'+(isSaved()?'Saved automatically':'Progress not saved')+'</span></div><section class="activity math-player science-player" data-science-lesson="'+l.id+'" '+(st.type==='finish'?'':'data-narration-step="science:'+l.id+':'+i+'" ')+'data-science-step="'+i+'" data-science-type="'+st.type+'"><div class="eyebrow">'+(st.type==='word'?'Meet one word':st.type==='question'?'A little question':st.type==='recap'?'Remember our discovery':'Look and explore')+'</div><h1>'+esc(l.title)+'</h1>'+body+navigation+'<p id="audio-status" class="status" role="status"></p></section><details class="science-parent"><summary>For parents · About this model</summary><p>'+esc(l.parent)+'</p></details>';
 }
 // The lesson after this one in the card order (null after the last).
 const nextLesson=()=>scienceLessons[scienceLessons.findIndex(l=>l.id===selected)+1]||null;
 function speak(){const st=displayed();if(st.type==='finish')return;play(st.type==='word'?[{key:'science-word:'+st.word,target:'.science-vocab-word'},{key:'text:'+st.text}]:[{key:'text:'+(st.type==='question'?st.prompt:st.text)}]);}
 function bind(){const root=document.querySelector('.science-player');if(!root)return;const key=selected+':'+p().step+':'+motionSerial;if(key===lastBound)return;stopMotion();lastBound=key;if(scienceMotionScenes.has(displayed().scene))stopMotion=animateScienceScene(root);}
 function handle(d){const action=d.action.replace('stages-science-','');if(action==='open'){stop();open(d.id);}else if(action==='audio')speak();else if(action==='stop')stop();else if(action==='animation'){stopMotion();stopMotion=animateScienceScene(document.querySelector('.science-player'));}
  else if(action==='next'){if(!ready())return;stop();const st=current();if(st.type==='word'&&!state().wordsMet.includes(st.word))state().wordsMet.push(st.word);if(!p().completed.includes(p().step))p().completed.push(p().step);p().step=Math.min(scienceSteps(lesson()).length-1,p().step+1);if(current().type==='finish')p().done=true;save();render();}
  else if(action==='previous'){stop();p().step=Math.max(0,p().step-1);save();render();}
  else if(action==='explore'){const st=current(),o=st.action?.options.find(o=>o.id===d.value);if(!o)return;stop();const e=p().experiments[st.action.id]??={value:o.id,tried:[]};e.value=o.id;if(!e.tried.includes(o.id))e.tried.push(o.id);motionSerial++;save();render(false);}
  else if(action==='answer'){const st=current();if(st.type!=='question'||correct(st)||!st.choices.some(c=>c.id===d.value))return;stop();const a=attempt(st),right=d.value===st.answer;a.tries++;a.firstCorrect??=right;onAttempt(scienceQuestionId(lesson(),st),right,a.assisted);if(!right){a.misses++;a.assisted=true;}p().answers[st.id]=d.value;save();render(false);play([{key:(right?'science-feedback:':'science-hint:')+scienceQuestionId(lesson(),st),target:'.science-feedback'},...(!right&&a.misses>=2?[{key:'science-demo:'+scienceQuestionId(lesson(),st),target:'.science-demonstration'}]:[])]);if(right)document.querySelector('[data-action=stages-science-next]')?.focus({preventScroll:true});}
  else if(action==='revisit'){stop();p().step=0;save();render();}
   else if(action==='next-lesson'&&nextLesson()){stop();open(nextLesson().id);}
 }
 function parentReport(){const s=getProgress().science;if(!s)return '';return '<section class="side-card"><h2>English for Science · This profile</h2><p>'+scienceLessons.filter(l=>s.lessons[l.id]?.done).length+' of 10 lessons practised. Stars and answer choices do not establish independent reading or science mastery.</p><ul>'+scienceLessons.filter(l=>s.lessons[l.id]).map(l=>{const pr=s.lessons[l.id];return '<li><b>'+esc(l.title)+'</b> · '+(pr.done?'practice complete':'saved step '+(pr.step+1))+' · '+Object.values(pr.attempts).reduce((n,a)=>n+a.misses,0)+' missed answers'+(Object.values(pr.attempts).some(a=>a.assisted)?' · some answers with help':'')+'</li>';}).join('')+'</ul><p>Missed science questions return in the existing review. Revisit the picture and demonstration and say the sentence together.</p></section>';}
 return{home,html,open,handle,bind,parentReport,cancel:()=>{stopMotion();stopMotion=()=>{};lastBound=null;}};
}
